import { useState } from 'react';

export function useUndoSimple(initial) {
  const [value, setValue] = useState(initial);
  const [prev, setPrev] = useState(undefined);
  return {
    value,
    set: (newValue) => { setPrev(value); setValue(newValue); },
    undo: () => { if (prev !== undefined) { setValue(prev); setPrev(undefined); } },
    canUndo: prev !== undefined,
  };
}
